package com.company.tpm.authorization; import com.company.tpm.common.BaseEntity; import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="roles") public class Role extends BaseEntity { @Column(nullable=false,unique=true,length=50) private String code; private String name; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="role_permissions",joinColumns=@JoinColumn(name="role_id"),inverseJoinColumns=@JoinColumn(name="permission_id")) private Set<Permission> permissions=new HashSet<>(); protected Role(){} public String getCode(){return code;} public Set<Permission> getPermissions(){return Set.copyOf(permissions);} }
